program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    foreground = [v for v in counts if v != bg]
    if not foreground:
        return [row[:] for row in grid]
    outside_color = max(foreground, key=lambda v: counts[v])
    fill = 4
    seen = set()
    out = [row[:] for row in grid]
    for sr in range(h):
        for sc in range(w):
            if grid[sr][sc] != bg or (sr, sc) in seen:
                continue
            q = deque([(sr, sc)])
            seen.add((sr, sc))
            component = []
            while q:
                r, c = q.popleft()
                component.append((r, c))
                for dr, dc in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    nr, nc = r + dr, c + dc
                    if (0 <= nr < h and 0 <= nc < w and grid[nr][nc] == bg
                            and (nr, nc) not in seen):
                        seen.add((nr, nc))
                        q.append((nr, nc))
            r0 = min(r for r, c in component); r1 = max(r for r, c in component)
            c0 = min(c for r, c in component); c1 = max(c for r, c in component)
            touches = set()
            for r, c in component:
                if r == 0: touches.add('top')
                if r == h - 1: touches.add('bottom')
                if c == 0: touches.add('left')
                if c == w - 1: touches.add('right')
            # A hole is normally enclosed by the outline. Treat the canvas edge
            # as one wall too when it completes a rectangular enclosure.
            edge_cavity = (len(touches) == 1 and r1-r0+1 >= 2 and c1-c0+1 >= 2
                           and len(component) == (r1-r0+1)*(c1-c0+1))
            if not touches or edge_cavity:
                for r, c in component:
                    out[r][c] = fill
    return out
'''
